UPDATE credit_application
SET next_poll_at = #{nextPollAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{id}

UPDATE credit_application
SET freeze_end_at = #{freezeEndAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
